<?php namespace App\Repositories; use App\Core\Database; final class PaymentRepository{public function all(int $limit=100):array{$s=Database::pdo()->query('SELECT * FROM invoice_payments ORDER BY id DESC LIMIT '.(int)$limit);return $s->fetchAll();}public function find(int $id):?array{$s=Database::pdo()->prepare('SELECT * FROM invoice_payments WHERE id=?');$s->execute([$id]);$r=$s->fetch();return $r?:null;}}